async function updateIban(userId, iban) {
  await redis.del(`acct:${userId}`);
  await db.query('UPDATE accounts SET iban=$1 WHERE id=$2', [iban, userId]);
}

async function getAccount(userId) {
  const hit = await redis.get(`acct:${userId}`);
  if (hit !== null) return JSON.parse(hit);
  const row = await db.one('SELECT * FROM accounts WHERE id=$1', [userId]);
  await redis.set(`acct:${userId}`, JSON.stringify(row), { expiration: { type: 'EX', value: 600 } });
  return row;
}

async function onHeadlineEdit(id, article) {
  await db.saveArticle(id, article);
  await redis.set(`article:${id}`, JSON.stringify(article));
}
